 function submit(event:React.FormEvent){event.preventDefault();if(owner.current||unknown||refreshing)return;let text:string;try{text=normalizeText(draft);}catch(error){setError(error instanceof Error?error.message:"Błędny komentarz");return;}const outgoing=attempt.current?.text===text?attempt.current:{clientId:newId(),text};attempt.current=outgoing;owner.current=true;setError("");start(async()=>{addOptimistic(outgoing);try{let saved:Comment;try{saved=parseComment(await api.add(outgoing));if(saved.clientId!==outgoing.clientId)throw new MutationFailure("Niespójne potwierdzenie","unknown");}catch(error){if(active.current){const uncertain=!(error instanceof MutationFailure)||error.outcome==="unknown";setUnknown(uncertain);setError(uncertain?"Nie potwierdzono wyniku. Odśwież dane przed ponowieniem.":"Serwer odrzucił komentarz. Popraw lub ponów.");}return;}startTransition(()=>{onConfirmed(saved);});if(active.current){setDraft("");setUnknown(false);attempt.current=null;}}finally{owner.current=false;}});}
 async function refresh(){if(owner.current||refreshing)return;setRefreshing(true);setError("");try{const rows=await api.list();startTransition(()=>{onReload(rows);});if(active.current){if(attempt.current&&rows.some(item=>item.clientId===attempt.current!.clientId)){setDraft("");attempt.current=null;}setUnknown(false);}}catch{if(active.current)setError("Nie udało się sprawdzić danych. Nie wysyłaj ponownie w ciemno.");}finally{if(active.current)setRefreshing(false);}}
 return <section><h2>Komentarze</h2>{optimistic.length?<ul>{optimistic.map(comment=><li key={comment.clientId} style={{opacity:comment.sending?.6:1}}>{comment.text}{comment.sending&&<span> — wysyłanie…</span>}</li>)}</ul>:<p>Brak komentarzy.</p>}<form onSubmit={submit}><fieldset disabled={pending||refreshing||unknown}><label>Komentarz<textarea value={draft} maxLength={2000} onChange={event=>{setDraft(event.currentTarget.value);attempt.current=null;}}/></label><button type="submit">Dodaj komentarz</button></fieldset></form><p role="status">{pending?"Zapis trwa…":refreshing?"Sprawdzanie danych…":""}</p>{error&&<p role="alert">{error}</p>}<button type="button" disabled={pending||refreshing} onClick={()=>void refresh()}>Odśwież komentarze</button></section>;}

