test("komentarz pojawia się przed odpowiedzią, a sukces nie tworzy duplikatu",async()=>{const task=deferred<Comment>(),api={add:vi.fn(()=>task.promise),list:vi.fn(async()=>[])};render(<Harness api={api}/>);await submit();expect(screen.getByRole("listitem")).toHaveTextContent("wysyłanie");expect(screen.getByRole("textbox")).toBeDisabled();await act(async()=>task.resolve({id:"saved-1",clientId:"request-1",text:"Mój komentarz"}));await waitFor(()=>expect(screen.getAllByRole("listitem")).toHaveLength(1));expect(screen.queryByText(/wysyłanie/)).not.toBeInTheDocument();expect(screen.getByRole("textbox")).toHaveValue("");expect(api.add).toHaveBeenCalledTimes(1);});
test("odrzucony zapis sam cofa warstwę optymistyczną i zachowuje draft",async()=>{const task=deferred<Comment>(),api={add:vi.fn(()=>task.promise),list:vi.fn(async()=>[])};render(<Harness api={api}/>);await submit();await act(async()=>task.reject(new MutationFailure("400","rejected")));expect(await screen.findByRole("alert")).toHaveTextContent("odrzucił");expect(screen.queryByRole("listitem")).not.toBeInTheDocument();expect(screen.getByRole("textbox")).toHaveValue("Mój komentarz");expect(screen.getByRole("button",{name:"Dodaj komentarz"})).toBeEnabled();});
test("rebase zachowuje potwierdzoną wiadomość otrzymaną w trakcie zapisu",async()=>{const task=deferred<Comment>(),api={add:vi.fn(()=>task.promise),list:vi.fn(async()=>[])};render(<Harness api={api}/>);await submit();await act(async()=>fireEvent.click(screen.getByRole("button",{name:"Dodaj z tła"})));expect(screen.getAllByRole("listitem")).toHaveLength(2);await act(async()=>task.reject(new MutationFailure("400","rejected")));expect(await screen.findByText("Z tła")).toBeVisible();expect(screen.getAllByRole("listitem")).toHaveLength(1);});
test("niepewny wynik blokuje drugi POST do czasu sprawdzenia danych",async()=>{const task=deferred<Comment>(),api={add:vi.fn(()=>task.promise),list:vi.fn(async()=>[{id:"saved",clientId:"request-1",text:"Mój komentarz"}])};render(<Harness api={api}/>);await submit();await act(async()=>task.reject(Error("network")));expect(await screen.findByRole("alert")).toHaveTextContent("Odśwież dane");expect(screen.getByRole("button",{name:"Dodaj komentarz"})).toBeDisabled();await act(async()=>fireEvent.click(screen.getByRole("button",{name:"Odśwież komentarze"})));await waitFor(()=>expect(screen.getByRole("textbox")).toHaveValue(""));expect(screen.getAllByRole("listitem")).toHaveLength(1);expect(api.add).toHaveBeenCalledTimes(1);});
test("po sprawdzeniu braku zapisu retry zachowuje identyfikator próby",async()=>{const first=deferred<Comment>(),second=deferred<Comment>(),api={add:vi.fn().mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise),list:vi.fn(async()=>[])};render(<Harness api={api}/>);await submit();await act(async()=>first.reject(Error("network")));await act(async()=>fireEvent.click(screen.getByRole("button",{name:"Odśwież komentarze"})));await waitFor(()=>expect(screen.getByRole("button",{name:"Dodaj komentarz"})).toBeEnabled());await act(async()=>fireEvent.click(screen.getByRole("button",{name:"Dodaj komentarz"})));expect(api.add.mock.calls[0][0].clientId).toBe(api.add.mock.calls[1][0].clientId);await act(async()=>second.resolve({id:"saved",clientId:"request-1",text:"Mój komentarz"}));});
test("walidacja nie uruchamia akcji optymistycznej ani API",async()=>{const api={add:vi.fn(),list:vi.fn(async()=>[])};render(<Harness api={api}/>);await submit("a");expect(screen.getByRole("alert")).toHaveTextContent("3–2000");expect(api.add).not.toHaveBeenCalled();expect(screen.queryByRole("listitem")).not.toBeInTheDocument();});
